const fs=require('fs'),path=require('path'),http=require('http');
const {chromium}=require('playwright');
const sharp=require('sharp');
const root=path.resolve(__dirname,'..'),files=['first-grade-math-word-problem-reading','toddler-throwing-toys'];
const server=http.createServer((req,res)=>{const file=path.resolve(root,'.'+decodeURIComponent(new URL(req.url,'http://localhost').pathname));if(!file.startsWith(root+path.sep)||!fs.existsSync(file)||!fs.statSync(file).isFile()){res.writeHead(404);return res.end();}res.setHeader('Content-Type',({'.html':'text/html; charset=utf-8','.css':'text/css','.webp':'image/webp','.jpg':'image/jpeg','.png':'image/png'})[path.extname(file)]||'application/octet-stream');res.end(fs.readFileSync(file));});
(async()=>{let browser;try{await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+server.address().port;browser=await chromium.launch({headless:true,executablePath:'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe'});const page=await browser.newPage();await page.route('**/*',r=>r.request().url().startsWith(origin+'/')?r.continue():r.abort());const results=[];
for(const name of files)for(const width of [360,390,1440]){await page.setViewportSize({width,height:1000});await page.goto(origin+'/blog/'+name+'.html',{waitUntil:'networkidle'});await page.locator('article img').evaluateAll(a=>a.forEach(i=>i.loading='eager'));await page.waitForFunction(()=>[...document.querySelectorAll('article img')].every(i=>i.complete));const stats=await page.evaluate(()=>{const a=document.querySelector('article'),links=[...a.querySelectorAll('a[href*="link.coupang.com"]')],notice=a.querySelector('.affiliate-notice');return {overflow:document.documentElement.scrollWidth>innerWidth+1,images:[...a.querySelectorAll('img')].every(i=>i.naturalWidth>0),links:links.length,subIds:[...new Set(links.map(l=>new URL(l.href).searchParams.get('subid')))],sponsored:links.every(l=>l.rel.includes('sponsored')),notice:!!notice&&!!(notice.compareDocumentPosition(links[0])&Node.DOCUMENT_POSITION_FOLLOWING),buttons:links.every(l=>l.getBoundingClientRect().height>=52),figures:[...a.querySelectorAll('figure img')].every(i=>i.getBoundingClientRect().width<=640&&i.getBoundingClientRect().height<=441),width:a.getBoundingClientRect().width};});if(stats.overflow||!stats.images||stats.links!==2||stats.subIds.length!==1||!stats.sponsored||!stats.notice||!stats.buttons||!stats.figures||stats.width>930)throw Error(JSON.stringify({name,width,stats}));results.push({name,width,...stats});if(width!==360)await page.screenshot({path:path.join(root,'logs/existing-'+name+'-'+width+'.png'),fullPage:true});}
for(const name of files){await page.setViewportSize({width:390,height:1000});await page.goto(origin+'/blog/'+name+'.html',{waitUntil:'networkidle'});const images=page.locator('article img');for(let i=0;i<await images.count();i++){const img=images.nth(i);await img.scrollIntoViewIfNeeded();await img.evaluate(i=>i.decode());const buffer=await img.screenshot();const stats=await sharp(buffer).stats();if(stats.channels.slice(0,3).every(c=>c.stdev<4))throw Error('Blank painted image '+name+' '+i);if(name==='toddler-throwing-toys'&&i<2)fs.writeFileSync(path.join(root,`logs/throwing-image-painted-${i}.png`),buffer);}await page.evaluate(()=>scrollTo(0,0));await page.screenshot({path:path.join(root,'logs/existing-'+name+'-390.png'),fullPage:true});}
fs.writeFileSync(path.join(root,'logs/existing-articles-20261105-qa.json'),JSON.stringify({checks:results.length,failures:0,paintedImagesVerified:true,results},null,2));console.log(JSON.stringify({articles:2,checks:results.length,failures:0,paintedImagesVerified:true}));}finally{if(browser)await browser.close();await new Promise(r=>server.close(r));}})().catch(e=>{console.error(e.message);process.exitCode=1});
